"""Core Ledger primitives: append, verify, snapshot, ConflictError.

Story 1.6: ``Ledger.append`` enforces rid-based replay, conflict and tombstone
semantics. The verifier and writer share one canonical-bytes scheme (see
``format.py``); the ledger file on disk is the single source of truth.

Story 2.1: ``Ledger.verify`` reads the JSONL end-to-end from disk and recomputes
every line's hash. It MUST NOT read any field from in-memory state set by
``append``. A fresh ``Ledger`` instance pointing at the same file MUST produce
the same verdict.
"""

from __future__ import annotations

import json
import os
import os.path
import unicodedata
from pathlib import Path
from typing import Any, Union

from ledgerlock.format import GENESIS, canonical_bytes, line_hash
from ledgerlock.store import read_lines, write_atomic

PathLike = Union[str, os.PathLike[str]]


class ConflictError(Exception):
    """Raised when an incoming mutation conflicts with the most recent committed
    mutation for the same key (different ``rid``).
    """

    def __init__(
        self,
        key: str,
        incoming_rid: str,
        committed_rid: str,
        batch_index: int | None = None,
    ) -> None:
        self.key = key
        self.incoming_rid = incoming_rid
        self.committed_rid = committed_rid
        self.batch_index = batch_index
        super().__init__(
            f"rid conflict on key {key!r}: incoming={incoming_rid!r} "
            f"committed={committed_rid!r}"
        )


def _normalize_key(key: str) -> str:
    return unicodedata.normalize("NFC", key)


def _serialize_line(line: dict[str, Any]) -> bytes:
    """Serialize a line dict to the on-disk JSONL bytes (single ``\\n`` terminator)."""
    return json.dumps(line, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode(
        "utf-8"
    ) + b"\n"


class Ledger:
    """Append-only JSONL ledger with hash-chain integrity guarantees.

    The instance keeps no in-memory cache that the verifier would trust; every
    state decision inside ``append`` is derived from a re-read of the disk file.
    """

    def __init__(self, path: PathLike) -> None:
        self._path = os.fspath(path)

    @property
    def path(self) -> str:
        return self._path

    def append(
        self,
        op: tuple,
    ) -> tuple[dict[str, Any], bool, bool]:
        """Append a single mutation to the chain.

        *op* is a tuple of the form
        ``(op_name, key, value_or_None, rid, ts)`` where ``op_name`` is
        ``"put"`` or ``"delete"``. For ``delete``, the value slot is ignored and
        may be ``None``.

        Returns a triple ``(line, replayed, committed)`` where ``line`` is the
        line dict that ends up representing this ``rid`` on disk (the original
        committed line on a replay), ``replayed`` is True iff the call was a
        rid-based no-op, and ``committed`` is True iff a new line was added.

        Raises ``ConflictError`` when a different ``rid`` tries to mutate a key
        whose most recent committed mutation used a different ``rid``.
        """
        op_name, key, value, rid, ts = op
        if not isinstance(rid, str) or not rid:
            raise ValueError("rid must be a non-empty string")
        normalized_key = _normalize_key(key)

        existing_lines = self._read_existing_lines()
        last_for_key = self._find_last_for_key(existing_lines, normalized_key)

        if last_for_key is not None and last_for_key.get("id") == rid:
            return dict(last_for_key), True, False

        if last_for_key is not None and last_for_key.get("id") != rid:
            raise ConflictError(
                key=normalized_key,
                incoming_rid=rid,
                committed_rid=last_for_key.get("id", ""),
                batch_index=None,
            )

        if op_name == "put":
            payload = {
                "op": "put",
                "key": normalized_key,
                "value": value,
                "ts": ts,
                "id": rid,
            }
        elif op_name == "delete":
            payload = {
                "op": "delete",
                "key": normalized_key,
                "ts": ts,
                "id": rid,
            }
        else:
            raise ValueError(f"unknown op: {op_name!r}")

        prev_hash = existing_lines[-1]["hash"] if existing_lines else GENESIS
        payload["prev_hash"] = prev_hash
        payload["hash"] = line_hash(prev_hash, payload)

        new_lines = existing_lines + [payload]
        self._write_lines(new_lines)
        return dict(payload), False, True

    def verify(self) -> dict[str, Any]:
        """Read the JSONL end-to-end from disk and recompute every line's hash.

        Returns ``{"ok": True, "first_bad_index": None}`` for an intact chain
        and ``{"ok": False, "first_bad_index": i}`` for the first line whose
        stored hash does not match the recomputed hash or whose stored
        ``prev_hash`` does not match the previous line's stored hash.

        Raises ``FileNotFoundError`` if the ledger path does not exist.
        """
        try:
            raw = read_lines(self._path)
        except FileNotFoundError:
            raise

        prev_hash = GENESIS
        for index, raw_line in enumerate(raw):
            try:
                line = json.loads(raw_line.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                return {"ok": False, "first_bad_index": index}

            stored_prev_hash = line.get("prev_hash")
            stored_hash = line.get("hash")
            if stored_prev_hash != prev_hash:
                return {"ok": False, "first_bad_index": index}
            expected_hash = line_hash(prev_hash, line)
            if stored_hash != expected_hash:
                return {"ok": False, "first_bad_index": index}
            prev_hash = stored_hash

        return {"ok": True, "first_bad_index": None}

    def _read_existing_lines(self) -> list[dict[str, Any]]:
        try:
            raw = read_lines(self._path)
        except FileNotFoundError:
            return []
        return [json.loads(line.decode("utf-8")) for line in raw]

    @staticmethod
    def _find_last_for_key(
        lines: list[dict[str, Any]], normalized_key: str
    ) -> dict[str, Any] | None:
        for line in reversed(lines):
            if line.get("key") == normalized_key:
                return line
        return None

    def _write_lines(self, lines: list[dict[str, Any]]) -> None:
        serialized = [_serialize_line(line) for line in lines]
        write_atomic(self._path, serialized)

