from __future__ import annotations

import json
import unittest

from ledgerlock.format import GENESIS, canonical_bytes


class TestCanonicalBytes(unittest.TestCase):
    def test_basic_dict_encoding(self) -> None:
        line = {"op": "put", "key": "k", "value": "v", "ts": 100, "id": "r1"}
        expected = json.dumps(line, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        self.assertEqual(canonical_bytes(line), expected)

    def test_byte_identical_for_equal_dicts(self) -> None:
        a = {"op": "put", "key": "k", "value": "v"}
        b = {"op": "put", "key": "k", "value": "v"}
        self.assertEqual(canonical_bytes(a), canonical_bytes(b))

    def test_utf8_literal_for_non_ascii(self) -> None:
        line = {"key": "é", "value": "v"}
        encoded = canonical_bytes(line)
        self.assertIn(b"\xc3\xa9", encoded)
        self.assertNotIn(b"\\u00e9", encoded)
        self.assertEqual(encoded, canonical_bytes(line))

    def test_insertion_order_irrelevant(self) -> None:
        a = {"key": "k", "value": "v", "ts": 1}
        b = {"ts": 1, "key": "k", "value": "v"}
        self.assertEqual(canonical_bytes(a), canonical_bytes(b))

    def test_genesis_constant(self) -> None:
        self.assertEqual(GENESIS, "GENESIS")
        self.assertEqual(len(GENESIS), 7)

    def test_round_trip_through_json_loads(self) -> None:
        original = {"op": "put", "key": "k", "value": "v", "ts": 1}
        first = canonical_bytes(original)
        roundtripped = json.loads(first.decode("utf-8"))
        self.assertEqual(canonical_bytes(roundtripped), first)


if __name__ == "__main__":
    unittest.main()

