"""Tests for STORY-01-03: line_hash SHA-256 hex digest."""

from __future__ import annotations

import unittest

from ledgerlock.format import GENESIS, line_hash


class TestLineHash(unittest.TestCase):
    def test_returns_64_lowercase_hex(self) -> None:
        line = {"op": "put", "key": "k", "value": "v"}
        digest = line_hash(GENESIS, line)
        self.assertEqual(len(digest), 64)
        self.assertTrue(all(c in "0123456789abcdef" for c in digest))

    def test_distinct_prev_hash_distinct_digest(self) -> None:
        line = {"op": "put", "key": "k", "value": "v"}
        a = line_hash("a" * 64, line)
        b = line_hash("b" * 64, line)
        self.assertNotEqual(a, b)

    def test_ignores_existing_hash_fields(self) -> None:
        line_with_hash = {
            "op": "put",
            "key": "k",
            "value": "v",
            "hash": "deadbeef" * 8,
            "prev_hash": "cafebabe" * 8,
        }
        clean = {"op": "put", "key": "k", "value": "v"}
        self.assertEqual(line_hash(GENESIS, line_with_hash), line_hash(GENESIS, clean))

    def test_deterministic_for_same_input(self) -> None:
        line = {"op": "put", "key": "k", "value": "v"}
        self.assertEqual(line_hash(GENESIS, line), line_hash(GENESIS, line))

    def test_genesis_accepted_as_prev_hash(self) -> None:
        line = {"op": "put", "key": "k", "value": "v"}
        digest = line_hash(GENESIS, line)
        self.assertEqual(len(digest), 64)


if __name__ == "__main__":
    unittest.main()

